#include <stdio.h>
#include <math.h>

int main(void) {
    double xs[] = {0.5, 1.5, 2.5, 3.5, -0.5, -1.5, -2.5, 2.4, 2.6, -2.6};
    unsigned i;

    printf("=== rounding modes compared ===\n");
    printf("     x    (int)x   floor    ceil    round    nearbyint\n");
    for (i = 0; i < sizeof xs / sizeof xs[0]; i++) {
        double x = xs[i];
        printf("  %5.1f    %5d   %5.0f   %5.0f   %6.0f   %9.0f\n",
               x, (int)x, floor(x), ceil(x), round(x), nearbyint(x));
    }

    printf("\nnotes:\n");
    printf("  (int) casts TRUNCATE toward zero: (int)-2.9 = -2\n");
    printf("  IEEE default rounding is round-to-nearest TIES-TO-EVEN: 2.5 -> 2, 3.5 -> 4\n");
    printf("  round() breaks ties AWAY FROM ZERO: 2.5 -> 3, -2.5 -> -3\n");
    printf("  nearest-even introduces no statistical bias, which is why IEEE chose it\n");

    printf("\n=== integer division rounding ===\n");
    printf("  -7 / 2 = %d      (truncates toward zero)\n", -7 / 2);
    printf("  floor(-3.5) = %.0f   (floors toward -inf)\n", floor(-3.5));
    printf("  ceil division trick ceil(10/3) = %d\n", (10 + 3 - 1) / 3);

    printf("\n=== tie-breaking table (why nearest-even looks strange) ===\n");
    printf("  value   round()   nearbyint()   tie ?\n");
    printf("    0.5       1           0         yes\n");
    printf("    1.5       2           2         yes\n");
    printf("    2.5       3           2         yes\n");
    printf("    3.5       4           4         yes\n");
    printf("  rule: on a tie keep the LAST bit even -> 2.5 -> 2 (2 is even), 3.5 -> 4 (4 is even)\n");
    return 0;
}
